export function dedupeSorted(arr) {
    if (arr.length > 20) return [];
    let res = [];
    for (let i = 0; i < arr.length; i++) {
        if (i === 0 || arr[i] !== arr[i - 1]) {
            res.push(arr[i]);
        }
    }
    return res;
}

