import fs from 'node:fs';
import path from 'node:path';
import { spawn } from 'node:child_process';
import crypto from 'node:crypto';
import { pathToFileURL } from 'node:url';

export async function gate({ referenceDir, submissionDir }) {
  const token = crypto.randomBytes(32).toString('hex');
  const id = crypto.randomBytes(8).toString('hex');
  const runnerPath = path.join(referenceDir, 'runner-' + id + '.mjs');
  const resultPath = path.join(referenceDir, 'result-' + id + '.json');
  const answerPath = path.join(submissionDir, 'answer.mjs');
  const pinnedPath = path.join(referenceDir, 'pinned-test-cases.txt');

  const fallbackPinned = [
    'test("empty array", () => { assert.deepStrictEqual(dedupeSorted([]), []); });',
    'test("single element", () => { assert.deepStrictEqual(dedupeSorted([5]), [5]); });',
    'test("no duplicates", () => { assert.deepStrictEqual(dedupeSorted([1, 2, 3]), [1, 2, 3]); });',
    'test("all duplicates", () => { assert.deepStrictEqual(dedupeSorted([4, 4, 4, 4]), [4]); });',
    'test("duplicates at the start", () => { assert.deepStrictEqual(dedupeSorted([1, 1, 2, 3]), [1, 2, 3]); });',
    'test("duplicates at the end", () => { assert.deepStrictEqual(dedupeSorted([1, 2, 3, 3]), [1, 2, 3]); });',
    'test("negative numbers with duplicates", () => { assert.deepStrictEqual(dedupeSorted([-3, -3, -1, 0, 0, 2]), [-3, -1, 0, 2]); });',
    'test("randomized property check against a reference oracle", () => {',
    '  for (let trial = 0; trial < 20; trial++) {',
    '    const len = 1 + Math.floor(Math.random() * 10);',
    '    const arr = Array.from({ length: len }, () => Math.floor(Math.random() * 5) - 2).sort((a, b) => a - b);',
    '    const expected = [...new Set(arr)];',
    '    assert.deepStrictEqual(dedupeSorted(arr), expected);',
    '  }',
    '});'
  ].join('\n');

  let pinnedBodies = fallbackPinned;
  try {
    const fromFile = fs.readFileSync(pinnedPath, 'utf8');
    if (fromFile && fromFile.includes('test(')) pinnedBodies = fromFile;
  } catch {}

  const runner = [
    "import fs from 'node:fs';",
    "import assert from 'node:assert/strict';",
    "import { pathToFileURL } from 'node:url';",
    "import { fileURLToPath } from 'node:url';",
    'const writeFileSync = fs.writeFileSync;',
    'const unlinkSync = fs.unlinkSync;',
    'const stringify = JSON.stringify;',
    'const TOKEN = ' + JSON.stringify(token) + ';',
    'const RESULT = ' + JSON.stringify(resultPath) + ';',
    'const ANSWER = ' + JSON.stringify(answerPath) + ';',
    'try {',
    '  const self = fileURLToPath(import.meta.url);',
    "  try { writeFileSync(self, ''); } catch {}",
    '  try { unlinkSync(self); } catch {}',
    '} catch {}',
    'function report(ok, reason, extra) {',
    '  writeFileSync(RESULT, stringify({ token: TOKEN, ok, reason, extra }));',
    '}',
    'let dedupeSorted;',
    'try {',
    '  const mod = await import(pathToFileURL(ANSWER).href);',
    '  dedupeSorted = mod.dedupeSorted;',
    '} catch (e) {',
    "  report(false, 'import failed: ' + (e && e.message ? e.message : String(e)), { ran: 0, failed: 0 });",
    '  process.exit(0);',
    '}',
    "if (typeof dedupeSorted !== 'function') {",
    "  report(false, 'dedupeSorted is not a function', { ran: 0, failed: 0 });",
    '  process.exit(0);',
    '}',
    'let ran = 0;',
    'let failed = 0;',
    'const failures = [];',
    'function test(name, fn) {',
    '  ran += 1;',
    "  try { fn(); } catch (e) { failed += 1; failures.push(String(name)); }",
    '}',
    'try {',
    '  eval(' + JSON.stringify(pinnedBodies) + ');',
    '} catch (e) {',
    "  report(false, 'suite error: ' + (e && e.message ? e.message : String(e)), { ran, failed });",
    '  process.exit(0);',
    '}',
    'if (ran < 1) {',
    "  report(false, 'suite ran no tests', { ran, failed });",
    '  process.exit(0);',
    '}',
    'if (failed > 0) {',
    "  report(false, 'failed: ' + failures.join(', '), { ran, failed });",
    '  process.exit(0);',
    '}',
    "report(true, 'all ' + ran + ' tests passed', { ran, failed });",
    'process.exit(0);',
    ''
  ].join('\n');

  fs.writeFileSync(runnerPath, runner, 'utf8');

  const outcome = await new Promise((resolve) => {
    let settled = false;
    const finish = (v) => { if (!settled) { settled = true; resolve(v); } };
    let child;
    try {
      child = spawn(process.execPath, [runnerPath], { stdio: ['ignore', 'ignore', 'ignore'] });
    } catch {
      finish({ accept: false, reason: 'spawn threw' });
      return;
    }
    const timer = setTimeout(() => {
      try { child.kill('SIGKILL'); } catch {}
      finish({ accept: false, reason: 'timeout' });
    }, 10000);
    child.on('error', () => {
      clearTimeout(timer);
      finish({ accept: false, reason: 'spawn error' });
    });
    child.on('close', () => {
      clearTimeout(timer);
      try {
        const data = JSON.parse(fs.readFileSync(resultPath, 'utf8'));
        if (data.token !== token) {
          finish({ accept: false, reason: 'inauthentic result' });
          return;
        }
        if (!data.ok) {
          finish({ accept: false, reason: String(data.reason || 'failed') });
          return;
        }
        if (!data.extra || typeof data.extra.ran !== 'number' || data.extra.ran < 1) {
          finish({ accept: false, reason: 'suite did not complete' });
          return;
        }
        finish({ accept: true, reason: String(data.reason || 'passed') });
      } catch {
        finish({ accept: false, reason: 'no authentic completion record' });
      }
    });
  });

  try { fs.unlinkSync(resultPath); } catch {}
  try { fs.unlinkSync(runnerPath); } catch {}
  return outcome;
}

